const reqs = $('Build requests').all();

return $input.all().map((item, i) => {
  const r = item.json;
  const req = reqs[i].json;
  const rec = {
    company_id: req.company_id, model: req.model, run_label: req.run_label,
    prompt_tokens: r.usage?.input_tokens ?? 0,
    completion_tokens: r.usage?.output_tokens ?? 0,   // includes thinking tokens
    has_brief: false, raw_response: r,
  };

  if (r.error || !r.usage)            rec.status = 'api_error';
  else if (r.stop_reason === 'refusal')    rec.status = 'refusal';
  else if (r.stop_reason === 'max_tokens') rec.status = 'max_tokens';
  else {
    const text = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
    try {
      const out = JSON.parse(text);
      const ok = typeof out.confidence === 'number' && out.confidence >= 0 && out.confidence <= 1;
      Object.assign(rec, out, { has_brief: true, confidence: ok ? out.confidence : null });
      // Never repaired: empty evidence is stored as it came back and flagged.
      rec.status = !(out.evidence || '').trim() ? 'no_evidence'
                 : ok ? 'ok' : 'invalid_output';
    } catch (e) {
      rec.status = 'invalid_output';
    }
  }
  return { json: { payload: JSON.stringify(rec), status: rec.status, company_id: rec.company_id } };
});

// Run settings. C3 changes MODEL; a new prompt file changes PROMPT_VERSION.
const MODEL = 'claude-haiku-5-5';
const PROMPT_VERSION = 'v1';
const EFFORT = 'medium';      // same for both models, so only the model differs
const TEST_LIMIT = 30;         // 0 = all 30

const companies = $('Parse snapshot').first().json.data;
const system = $('Prompt text').first().json.data;
const evalIds = new Set($input.all().map(i => Number(i.json.id)));

function toText(html) {
  return (html || '')
    .replace(/<br\s*\/?>|<\/p>|<\/li>|<\/h\d>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n\n')
    .trim();
}

const schema = {
  type: 'object',
  properties: {
    is_real_signal: { type: 'boolean' },
    hiring_focus: { type: 'string' },
    team_context: { type: 'string' },
    evidence: { type: 'string' },
    personalization_line: { type: 'string' },
    confidence: { type: 'number' },
  },
  required: ['is_real_signal', 'hiring_focus', 'team_context',
             'evidence', 'personalization_line', 'confidence'],
  additionalProperties: false,
};

const selected = companies.filter(c => evalIds.has(c.company_id));
return selected.slice(0, TEST_LIMIT || selected.length).map(c => {
  // Identical descriptions are sent once: same information, fewer tokens.
  const seen = new Map();
  const parts = c.jobs.map((j, i) => {
    const head = `### Posting ${i + 1}: ${j.title}\n` +
                 `Location: ${j.location || 'unknown'} | Posted: ${(j.posted_at || '').slice(0, 10)}`;
    const text = toText(j.description);
    if (seen.has(text)) return `${head}\nDescription identical to posting ${seen.get(text)}.`;
    seen.set(text, i + 1);
    return `${head}\n${text}`;
  });
  return { json: {
    company_id: c.company_id,
    model: MODEL,
    run_label: PROMPT_VERSION,
    request: {
      model: MODEL,
      max_tokens: 16000,
      output_config: { effort: EFFORT, format: { type: 'json_schema', schema } },
      system,
      messages: [{ role: 'user', content: `Company: ${c.company_name}\n\n${parts.join('\n\n')}` }],
    },
  }};
});
